<?php
declare(strict_types=1);
$pageTitle='Смета';
require_once __DIR__.'/includes/header.php';
if(!$pdo){echo '<div class="admin-card"><h2 class="admin-card-title">Нет подключения к БД</h2></div>';require_once __DIR__.'/includes/footer.php';exit;}
$pdo->exec("CREATE TABLE IF NOT EXISTS estimate_projects(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,title VARCHAR(255) NOT NULL,client_name VARCHAR(255),city VARCHAR(150),status VARCHAR(30) NOT NULL DEFAULT 'draft',coefficient DECIMAL(10,4) NOT NULL DEFAULT 1.0000,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,KEY status(status),KEY updated_at(updated_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");
$pdo->exec("CREATE TABLE IF NOT EXISTS estimate_categories(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,estimate_id INT UNSIGNED NOT NULL,name VARCHAR(255) NOT NULL,sort_order INT NOT NULL DEFAULT 0,KEY estimate_id(estimate_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");
$pdo->exec("CREATE TABLE IF NOT EXISTS estimate_items(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,category_id INT UNSIGNED NOT NULL,name VARCHAR(255) NOT NULL,quantity DECIMAL(14,3) NOT NULL DEFAULT 1,unit VARCHAR(30) NOT NULL DEFAULT 'шт',price DECIMAL(14,2) NOT NULL DEFAULT 0,sort_order INT NOT NULL DEFAULT 0,KEY category_id(category_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");
$id=(int)($_GET['id']??0);if($id<=0)redirect('estimates.php');$q=$pdo->prepare("SELECT * FROM estimate_projects WHERE id=?");$q->execute([$id]);$estimate=$q->fetch();if(!$estimate)redirect('estimates.php');
function ecats(PDO $pdo,int $id):array{$q=$pdo->prepare("SELECT c.*,COALESCE(SUM(i.quantity*i.price),0) total,COUNT(i.id) item_count FROM estimate_categories c LEFT JOIN estimate_items i ON i.category_id=c.id WHERE c.estimate_id=? GROUP BY c.id ORDER BY c.sort_order,c.id");$q->execute([$id]);$a=$q->fetchAll();foreach($a as &$c){$q=$pdo->prepare("SELECT * FROM estimate_items WHERE category_id=? ORDER BY sort_order,id");$q->execute([(int)$c['id']);$c['items']=$q->fetchAll();}return $a;}
if($_SERVER['REQUEST_METHOD']==='POST'){csrf_check();$a=$_POST['action']??'';
if($a==='save_project'){$q=$pdo->prepare("UPDATE estimate_projects SET title=?,client_name=?,city=?,status=? WHERE id=?");$q->execute([trim($_POST['title']??'Новая смета'),trim($_POST['client_name']??''),trim($_POST['city']??''),$_POST['status']??'draft',$id]);redirect('estimate-edit.php?id='.$id);}
if($a==='save_coefficient'){$c=max(.001,(float)str_replace(',','.',$_POST['coefficient']??'1'));$q=$pdo->prepare("UPDATE estimate_projects SET coefficient=? WHERE id=?");$q->execute([$c,$id]);header('Content-Type: application/json');echo json_encode(['ok'=>true]);exit;}
if($a==='add_category'){$name=trim($_POST['name']??'');if($name!==''){$q=$pdo->prepare("SELECT COALESCE(MAX(sort_order),0)+1 FROM estimate_categories WHERE estimate_id=?");$q->execute([$id]);$s=(int)$q->fetchColumn();$q=$pdo->prepare("INSERT INTO estimate_categories(estimate_id,name,sort_order) VALUES(?,?,?)");$q->execute([$id,$name,$s]);}redirect('estimate-edit.php?id='.$id);}
if($a==='delete_category'){$c=(int)$_POST['category_id'];$q=$pdo->prepare("DELETE FROM estimate_items WHERE category_id=?");$q->execute([$c]);$q=$pdo->prepare("DELETE FROM estimate_categories WHERE id=? AND estimate_id=?");$q->execute([$c,$id]);redirect('estimate-edit.php?id='.$id);}
if($a==='add_item'){$c=(int)$_POST['category_id'];$n=trim($_POST['name']??'');$qty=max(.001,(float)str_replace(',','.',$_POST['quantity']??'1'));$u=trim($_POST['unit']??'шт');$p=max(0,(float)str_replace(',','.',$_POST['price']??'0'));if($n!==''){$q=$pdo->prepare("SELECT COALESCE(MAX(sort_order),0)+1 FROM estimate_items WHERE category_id=?");$q->execute([$c]);$s=(int)$q->fetchColumn();$q=$pdo->prepare("INSERT INTO estimate_items(category_id,name,quantity,unit,price,sort_order) SELECT ?,?,?,?,?,? FROM estimate_categories WHERE id=? AND estimate_id=?");$q->execute([$c,$n,$qty,$u,$p,$s,$c,$id]);}redirect('estimate-edit.php?id='.$id);}
if($a==='update_item'){$item=(int)$_POST['item_id'];$q=$pdo->prepare("UPDATE estimate_items i JOIN estimate_categories c ON c.id=i.category_id SET i.name=?,i.quantity=?,i.unit=?,i.price=? WHERE i.id=? AND c.estimate_id=?");$q->execute([trim($_POST['name']??''),max(.001,(float)str_replace(',','.',$_POST['quantity']??'1')),trim($_POST['unit']??'шт'),max(0,(float)str_replace(',','.',$_POST['price']??'0')),$item,$id]);redirect('estimate-edit.php?id='.$id);}
if($a==='delete_item'){$q=$pdo->prepare("DELETE i FROM estimate_items i JOIN estimate_categories c ON c.id=i.category_id WHERE i.id=? AND c.estimate_id=?");$q->execute([(int)$_POST['item_id'],$id]);redirect('estimate-edit.php?id='.$id);}
if($a==='add_catalog'){$c=(int)$_POST['category_id'];$q=$pdo->prepare("SELECT name,unit,price FROM quick_estimate_catalog WHERE id=? AND active=1");$q->execute([(int)$_POST['catalog_id']]);$x=$q->fetch();if($x){$qty=max(.001,(float)str_replace(',','.',$_POST['quantity']??'1'));$q=$pdo->prepare("SELECT COALESCE(MAX(sort_order),0)+1 FROM estimate_items WHERE category_id=?");$q->execute([$c]);$s=(int)$q->fetchColumn();$q=$pdo->prepare("INSERT INTO estimate_items(category_id,name,quantity,unit,price,sort_order) VALUES(?,?,?,?,?,?)");$q->execute([$c,$x['name'],$qty,$x['unit'],$x['price'],$s]);}redirect('estimate-edit.php?id='.$id);}}
$estimate=$pdo->query("SELECT * FROM estimate_projects WHERE id=".$id)->fetch();$cats=ecats($pdo,$id);$direct=0;$items=0;foreach($cats as $c){$direct+=(float)$c['total'];$items+=(int)$c['item_count'];}$coef=(float)$estimate['coefficient'];$base=$direct*$coef;$overhead=$base*.15;$profit=$base*.08;$vat=($base+$overhead+$profit)*.2;$grand=$base+$overhead+$profit+$vat;
$catalog=[];try{$catalog=$pdo->query("SELECT * FROM quick_estimate_catalog WHERE active=1 ORDER BY FIELD(category,'materials','countertop','hardware','fasteners'),name")->fetchAll();}catch(Throwable $e){}$labels=['materials'=>'ЛДСП / МДФ / Кромка','countertop'=>'Столешницы','hardware'=>'Фурнитура','fasteners'=>'Крепёж'];
?>
<div class="smeta-page"><div class="smeta-heading"><div><a href="estimates.php" class="smeta-back"><i class="bi bi-arrow-left"></i> Все сметы</a><div class="smeta-title-row"><div class="smeta-icon"><i class="bi bi-calculator"></i></div><div><div class="smeta-eyebrow">СМЕТНЫЙ ПРОЕКТ</div><h2><?=h($estimate['title'])?></h2><p><?=h($estimate['city']?:'Город не указан')?> · <?=h($estimate['client_name']?:'Заказчик не указан')?></p></div></div></div><div class="smeta-heading-actions"><button class="admin-btn admin-btn--outline" data-bs-toggle="modal" data-bs-target="#editEstimate"><i class="bi bi-pencil"></i> Карточка</button><button class="admin-btn admin-btn--primary" data-bs-toggle="modal" data-bs-target="#addCategory"><i class="bi bi-plus-lg"></i> Добавить раздел</button></div></div>
<div class="smeta-summary"><div><span>ИТОГО ПО СМЕТЕ</span><strong id="smetaGrand"><?=number_format($grand,0,',',' ')?> ₽</strong><small>НР 15% · СП 8% · НДС 20%</small></div><div class="smeta-summary-stats"><div><b><?=count($cats)?></b> разделов</div><div><b><?=$items?></b> позиций</div><div><b id="topCoef">× <?=number_format($coef,3,',','')?></b> коэффициент</div></div></div>
<div class="smeta-toolbar"><div><strong>СМЕТА</strong><span><?=count($cats)?> разделов · <?=$items?> позиций</span></div><button class="smeta-text-btn" data-bs-toggle="modal" data-bs-target="#addCategory"><i class="bi bi-plus"></i> Добавить раздел</button></div>
<div class="estimate-list smeta-estimate-list">
<?php foreach($cats as $n=>$cat):?><div class="estimate-group"><div class="group-heading"><span class="group-number"><?=str_pad($n+1,2,'0',STR_PAD_LEFT)?></span><h3><?=h($cat['name'])?></h3><span><?=$cat['item_count']?> позиций</span><strong><?=number_format($cat['total'],0,',',' ')?> ₽</strong><form method="post" onsubmit="return confirm('Удалить раздел и позиции?')"><?=csrf_field()?><input type="hidden" name="action" value="delete_category"><input type="hidden" name="category_id" value="<?=$cat['id']?>"><button class="smeta-row-more"><i class="bi bi-three-dots"></i></button></form></div><div class="estimate-table"><div class="table-head"><span>ПОЗИЦИЯ</span><span>КОЛИЧЕСТВО</span><span>ЕД.</span><span>ЦЕНА</span><span>СУММА</span><span></span></div>
<?php foreach($cat['items'] as $it):$sum=$it['quantity']*$it['price'];?><div class="table-row smeta-row"><div class="work-name"><i class="work-dot"></i><span class="rv-name"><?=h($it['name'])?></span><input class="cell-input re-name" value="<?=h($it['name'])?>" hidden></div><span class="rv-qty"><?=rtrim(rtrim(number_format($it['quantity'],3,',',' '),'0'),',')?></span><input class="cell-input re-qty" value="<?=h($it['quantity'])?>" hidden><span class="rv-unit"><?=h($it['unit'])?></span><input class="cell-input re-unit" value="<?=h($it['unit'])?>" hidden><span class="rv-price"><?=number_format($it['price'],2,',',' ')?> ₽</span><input class="cell-input re-price" value="<?=h($it['price'])?>" hidden><strong class="rv-sum"><?=number_format($sum,2,',',' ')?> ₽</strong><div class="row-actions"><button type="button" class="edit-row"><i class="bi bi-pencil"></i></button><form method="post" onsubmit="return confirm('Удалить позицию?')"><?=csrf_field()?><input type="hidden" name="action" value="delete_item"><input type="hidden" name="item_id" value="<?=$it['id']?>"><button><i class="bi bi-trash3"></i></button></form><button type="button" class="save-row" hidden><i class="bi bi-check-lg"></i></button><button type="button" class="cancel-row" hidden><i class="bi bi-x-lg"></i></button><form class="inline-edit-form" method="post"><?=csrf_field()?><input type="hidden" name="action" value="update_item"><input type="hidden" name="item_id" value="<?=$it['id']?>"><input name="name"><input name="quantity"><input name="unit"><input name="price"></form></div></div><?php endforeach;?>
<button class="add-row add-manual" type="button" data-cat="<?=$cat['id']?>" data-bs-toggle="modal" data-bs-target="#addItem"><i class="bi bi-plus-lg"></i> Добавить позицию</button><button class="smeta-add-catalog" type="button" data-cat="<?=$cat['id']?>" data-bs-toggle="modal" data-bs-target="#catalog"><i class="bi bi-box-seam"></i> Добавить из каталога</button></div></div><?php endforeach;?>
<?php if(!$cats):?><div class="smeta-empty"><i class="bi bi-list-check"></i><h3>Смета пока пустая</h3><p>Создайте первый раздел и добавьте позиции.</p></div><?php endif;?>
<div class="estimate-totals smeta-totals"><div><span>Прямые затраты</span><b id="tDirect"><?=number_format($direct,2,',',' ')?> ₽</b></div><div><span>Коэффициент</span><label class="coef-input"><span>×</span><input id="coef" type="number" min=".001" step=".001" value="<?=h($coef)?>"></label></div><div><span>Затраты с коэффициентом</span><b id="tBase"><?=number_format($base,2,',',' ')?> ₽</b></div><div><span>Накладные расходы (НР) · 15%</span><b id="tOver"><?=number_format($overhead,2,',',' ')?> ₽</b></div><div><span>Сметная прибыль (СП) · 8%</span><b id="tProfit"><?=number_format($profit,2,',',' ')?> ₽</b></div><div><span>НДС · 20%</span><b id="tVat"><?=number_format($vat,2,',',' ')?> ₽</b></div><div class="grand-total"><span>Итого в текущем уровне цен</span><strong id="tGrand"><?=number_format($grand,2,',',' ')?> ₽</strong></div></div></div></div>
<div class="modal fade" id="editEstimate"><div class="modal-dialog modal-dialog-centered"><div class="modal-content"><form method="post"><div class="modal-header"><h5 class="modal-title">Карточка сметы</h5><button type="button" class="btn-close" data-bs-dismiss="modal"></button></div><div class="modal-body"><?=csrf_field()?><input type="hidden" name="action" value="save_project"><div class="smeta-form-grid"><label><span>Название</span><input name="title" value="<?=h($estimate['title'])?>"></label><label><span>Заказчик</span><input name="client_name" value="<?=h($estimate['client_name'])?>"></label><label><span>Город</span><input name="city" value="<?=h($estimate['city'])?>"></label><label><span>Статус</span><select name="status"><?php foreach(['draft'=>'Черновик','in_progress'=>'В работе','review'=>'На согласовании','completed'=>'Завершена','archived'=>'Архив'] as $v=>$t):?><option value="<?=$v?>" <?=$estimate['status']===$v?'selected':''?>><?=$t?></option><?php endforeach;?></select></label></div></div><div class="modal-footer"><button type="button" class="admin-btn admin-btn--outline" data-bs-dismiss="modal">Отмена</button><button class="admin-btn admin-btn--primary">Сохранить</button></div></form></div></div></div>
<div class="modal fade" id="addCategory"><div class="modal-dialog modal-dialog-centered"><div class="modal-content"><form method="post"><div class="modal-header"><h5 class="modal-title">Новый раздел</h5><button type="button" class="btn-close" data-bs-dismiss="modal"></button></div><div class="modal-body"><?=csrf_field()?><input type="hidden" name="action" value="add_category"><label class="smeta-field"><span>Название</span><input name="name" required placeholder="Материалы, Фасады, Фурнитура..."></label></div><div class="modal-footer"><button type="button" class="admin-btn admin-btn--outline" data-bs-dismiss="modal">Отмена</button><button class="admin-btn admin-btn--primary">Создать</button></div></form></div></div></div>
