<script>
(()=>{const n=v=>parseFloat(String(v).replace(',','.'))||0,m=v=>new Intl.NumberFormat('ru-RU',{minimumFractionDigits:2,maximumFractionDigits:2}).format(v)+' ₽';function calc(){let d=0;document.querySelectorAll('.smeta-row').forEach(r=>{d+=n(r.querySelector('.re-qty')?.value||r.querySelector('.rv-qty')?.textContent)*n(r.querySelector('.re-price')?.value||r.querySelector('.rv-price')?.textContent)});let c=Math.max(.001,n(document.getElementById('coef')?.value||1)),b=d*c,o=b*.15,p=b*.08,v=(b+o+p)*.2,g=b+o+p+v;[['tDirect',d],['tBase',b],['tOver',o],['tProfit',p],['tVat',v],['tGrand',g]].forEach(([i,x])=>{let e=document.getElementById(i);if(e)e.textContent=m(x)});let e=document.getElementById('smetaGrand');if(e)e.textContent=new Intl.NumberFormat('ru-RU',{maximumFractionDigits:0}).format(g)+' ₽';e=document.getElementById('topCoef');if(e)e.textContent='× '+c.toFixed(3).replace('.',',')}document.getElementById('coef')?.addEventListener('input',calc);
document.querySelectorAll('.edit-row').forEach(b=>b.onclick=()=>{let r=b.closest('.smeta-row');r.classList.add('is-editing');r.querySelectorAll('.rv-name,.rv-qty,.rv-unit,.rv-price').forEach(x=>x.hidden=true);r.querySelectorAll('.re-name,.re-qty,.re-unit,.re-price').forEach(x=>x.hidden=false);b.hidden=true;r.querySelector('.row-actions form').style.display='none';r.querySelector('.save-row').hidden=false;r.querySelector('.cancel-row').hidden=false});
document.querySelectorAll('.cancel-row').forEach(b=>b.onclick=()=>location.reload());document.querySelectorAll('.save-row').forEach(b=>b.onclick=()=>{let r=b.closest('.smeta-row'),f=r.querySelector('.inline-edit-form');f.elements.name.value=r.querySelector('.re-name').value;f.elements.quantity.value=r.querySelector('.re-qty').value;f.elements.unit.value=r.querySelector('.re-unit').value;f.elements.price.value=r.querySelector('.re-price').value;f.submit()});
document.querySelectorAll('.add-manual').forEach(b=>b.onclick=()=>document.getElementById('itemCat').value=b.dataset.cat);let cat=0;document.querySelectorAll('.smeta-add-catalog').forEach(b=>b.onclick=()=>{cat=+b.dataset.cat;document.getElementById('catalogCat').value=cat});document.querySelectorAll('.catalog-item').forEach(b=>b.onclick=()=>{document.querySelectorAll('.catalog-item').forEach(x=>x.classList.remove('selected'));b.classList.add('selected');document.getElementById('catalogId').value=b.dataset.id;document.getElementById('catalogName').textContent=b.dataset.title;document.getElementById('catalogSelected').hidden=false;document.getElementById('catalogAdd').disabled=false});document.getElementById('catalogQty')?.addEventListener('input',e=>document.getElementById('catalogQuantity').value=e.target.value);document.getElementById('catalogForm')?.addEventListener('submit',()=>document.getElementById('catalogQuantity').value=document.getElementById('catalogQty').value||1);document.getElementById('catalogSearch')?.addEventListener('input',e=>{let q=e.target.value.toLowerCase();document.querySelectorAll('.catalog-item').forEach(x=>x.style.display=!q||x.dataset.search.includes(q)?'flex':'none')});document.getElementById('coef')?.addEventListener('change',async e=>{let f=new FormData();f.append('csrf',<?=json_encode(csrf_token())?>);f.append('action','save_coefficient');f.append('coefficient',e.target.value);try{await fetch(location.href,{method:'POST',body:f})}catch(_){}});calc()})();
</script>
